def shiftGrid(grid: list[list[int]], row_shifts: list[int], col_shifts: list[int]) -> list[list[int]]:
    m, n = len(grid), len(grid[0])
    # Step 1: row shifts
    after_rows = [[0] * n for _ in range(m)]
    for r in range(m):
        sh = row_shifts[r] % n
        for c in range(n):
            after_rows[r][(c + sh) % n] = grid[r][c]

    # Step 2: col shifts
    final_grid = [[0] * n for _ in range(m)]
    for c in range(n):
        sh = col_shifts[c] % m
        for r in range(m):
            final_grid[(r + sh) % m][c] = after_rows[r][c]

    return final_grid

#include <vector>

class Solution {
public:
    std::vector<std::vector<int>> shiftGrid(
        std::vector<std::vector<int>>& grid,
        std::vector<int>& row_shifts,
        std::vector<int>& col_shifts
    ) {
        int m = grid.size(), n = grid[0].size();
        std::vector<std::vector<int>> after_rows(m, std::vector<int>(n));
        for (int r = 0; r < m; ++r) {
            int sh = (row_shifts[r] % n + n) % n;
            for (int c = 0; c < n; ++c) {
                after_rows[r][(c + sh) % n] = grid[r][c];
            }
        }

        std::vector<std::vector<int>> final_grid(m, std::vector<int>(n));
        for (int c = 0; c < n; ++c) {
            int sh = (col_shifts[c] % m + m) % m;
            for (int r = 0; r < m; ++r) {
                final_grid[(r + sh) % m][c] = after_rows[r][c];
            }
        }
        return final_grid;
    }
};

class Solution {
    public int[][] shiftGrid(int[][] grid, int[] rowShifts, int[] colShifts) {
        int m = grid.length, n = grid[0].length;
        int[][] afterRows = new int[m][n];
        for (int r = 0; r < m; r++) {
            int sh = (rowShifts[r] % n + n) % n;
            for (int c = 0; c < n; c++) {
                afterRows[r][(c + sh) % n] = grid[r][c];
            }
        }

        int[][] finalGrid = new int[m][n];
        for (int c = 0; c < n; c++) {
            int sh = (colShifts[c] % m + m) % m;
            for (int r = 0; r < m; r++) {
                finalGrid[(r + sh) % m][c] = afterRows[r][c];
            }
        }
        return finalGrid;
    }
